-- Seed daily_log with the MyFitnessPal export (2026-01-01 to 2026-06-30).
--
-- Run after supabase/daily_log.sql has created the table. Safe to re-run:
-- it upserts on `day`, so re-importing an overlapping export just refreshes
-- those days rather than duplicating them.
--
-- Nutrition only. Sleep columns stay null until that feed is connected, and
-- this deliberately does not overwrite sleep values that already exist.

on conflict (day) do update set
  kcal      = excluded.kcal,
  protein_g = excluded.protein_g,
  carbs_g   = excluded.carbs_g,
  fat_g     = excluded.fat_g,
  updated_at = now();
